"""Targeted own-session evidence selection. Not a full-library snapshot."""
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
import json
import math
import time
from .cloud_snapshot import PreparationError


def deny(code):
    raise PreparationError('target_' + code)


def instant(value):
    if not isinstance(value, str): deny('invalid_timestamp')
    try:
        t = datetime.fromisoformat(value.replace('Z', '+00:00'))
        return (t.replace(tzinfo=timezone.utc) if t.tzinfo is None else t).astimezone(timezone.utc)
    except ValueError: deny('invalid_timestamp')


def select_target(db, columns, excluded_ids, excluded_uuids, day, stage=lambda *args:None, deadline=None):
    def check():
        if deadline is not None and time.monotonic()>deadline: deny('timeout')
    check()
    try:
        local = datetime.strptime(day, '%Y-%m-%d').replace(tzinfo=ZoneInfo('America/New_York'))
    except ValueError: deny('invalid_day')
    start = local.astimezone(timezone.utc)
    end = (local + timedelta(days=1)).astimezone(timezone.utc)
    if not {'id','uuid','started_at','ended_at'} <= columns.get('sessions',set()): deny('session_schema')
    if not {'id','session_id','seq','events_json'} <= columns.get('session_chunks',set()): deny('chunk_schema')
    stage('target_session_headers','sessions')
    ids, uuids, open_count, excluded_count = [], [], 0, 0
    header_count=0;source_bytes=0
    for ident, uuid, a, b in db.execute('SELECT id,uuid,started_at,ended_at FROM sessions ORDER BY id'):
        check();header_count+=1
        if header_count>100000: deny('header_limit')
        a = instant(a); b = instant(b) if b is not None else None
        if b is not None and b < a: deny('invalid_interval')
        if a >= end or (b is not None and b <= start): continue
        if ident in excluded_ids or uuid in excluded_uuids:
            excluded_count += 1; continue
        if type(ident) is not int or not isinstance(uuid,str) or not uuid: deny('session_identity')
        ids.append(ident); uuids.append(uuid);open_count += b is None
    if not ids: deny('no_own_sessions')
    if len(ids)>1000: deny('session_limit')
    track_ids=set(); chunk_count=event_count=0; stem_events=tenure_events=0
    for ident in ids:
        check()
        expected=0; last_t=-math.inf
        stage('target_chunk_fetch','session_chunks')
        for seq, raw in db.execute('SELECT seq,events_json FROM session_chunks WHERE session_id=? ORDER BY seq,id',(ident,)):
            check()
            if chunk_count>=100000: deny('chunk_limit')
            if not isinstance(raw,str): deny('invalid_events')
            source_bytes+=len(raw.encode('utf-8'))
            if source_bytes>640*1024*1024: deny('source_byte_limit')
            if type(seq) is not int or seq!=expected: deny('chunk_sequence_gap_or_duplicate')
            expected+=1; chunk_count+=1
            stage('target_event_parse','session_chunks',expected)
            try: events=json.loads(raw,parse_constant=lambda _:deny('nonfinite_event'))
            except (TypeError,ValueError,RecursionError): deny('invalid_events')
            check()
            if not isinstance(events,list): deny('invalid_events')
            for event in events:
                check()
                if not isinstance(event,dict): deny('invalid_event')
                t=event.get('t')
                if isinstance(t,bool) or not isinstance(t,(int,float)) or not math.isfinite(t) or t<last_t: deny('event_clock')
                last_t=t;event_count+=1
                if event_count>2000000: deny('event_limit')
                if event.get('kind')=='load':
                    tid=event.get('trackId')
                    if tid is not None:
                        if type(tid) is not int or tid<=0: deny('track_identity')
                        track_ids.add(tid)
                if event.get('kind')=='init': deny('unexpected_session_init')
                if str(event.get('control','')).startswith('stem'): stem_events+=1
                if event.get('kind')=='tenure': tenure_events+=1
            stage('target_chunk_fetch','session_chunks',expected)
        if not expected: deny('empty_session')
    if not track_ids: deny('no_loaded_tracks')
    if len(track_ids)>5000: deny('track_limit')
    stage('target_track_dependencies','tracks')
    check()
    present={r[0] for r in db.execute('SELECT id FROM tracks WHERE id IN ('+','.join('?' for _ in track_ids)+')',tuple(track_ids))}
    check()
    if not track_ids<=present: deny('missing_track')
    filters={'sessions':('id',tuple(ids)), 'session_chunks':('session_id',tuple(ids)), 'tracks':('id',tuple(sorted(track_ids)))}
    for table in ('beatgrids','metric_ladders','hotcues'):
        if table in columns:
            if 'track_id' not in columns[table]: deny('dependency_schema')
            filters[table]=('track_id',tuple(sorted(track_ids)))
    return {'filters':filters,'coverage':{'scope':'targeted_own_session_history_not_library_sync',
        'day':day,'timezone':'America/New_York','startUtc':start.isoformat(),'endUtc':end.isoformat(),
        'sessions':len(ids),'openSessionsEndUncertain':open_count,'excludedOverlappingPeerGroupSessions':excluded_count,
        'chunks':chunk_count,'events':event_count,'referencedTracks':len(track_ids),'stemControlEvents':stem_events,
        'machineTenureEvents':tenure_events,'fullSelectedSessionsPreserved':True,
        'exclusions':['audio_and_stems','local_paths_and_hashes','unrelated_library_rows','takes_and_routines_derivable_from_whole_sessions'],
        'renderReady':False,'fullLibraryComplete':False,'uploadReady':False}}

