"""Local-only source inventory, no network or payload artifact.

Uses existing1MiB SQLite bound,120s scan/130s child watchdog,640MiB canonical
row envelopes and1million source rows. Wire validation limits are unchanged.
"""
import json
from pathlib import Path
import subprocess
import sys
import time
import threading
import os
import tempfile
sys.path.insert(0,str(Path(__file__).resolve().parents[2]))
from backend.cloud_snapshot import inventory_snapshot, _prepare_snapshot, PreparationError


def measure(path, *, validator_command=None, wall_seconds=130, target_day=None, capture_path=None):
    started=time.monotonic()
    if capture_path is not None and Path(capture_path).exists():
        return {'status':'blocked_incomplete_measurement','code':'target_output_exists','cloudUpload':False}
    artifact=None;temp_path=None;process=None;watchdog=None
    expired=threading.Event()
    try:
        if capture_path is not None:
            capture_path=Path(capture_path)
            fd,temp_path=tempfile.mkstemp(prefix='.nov7-capture-',dir=capture_path.parent)
            artifact=os.fdopen(fd,'w',encoding='utf-8')
        process=subprocess.Popen(validator_command or ['node',str(Path(__file__).with_suffix('.mjs'))],
            stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        def expire():
            expired.set()
            if process.poll() is None: process.kill()
        watchdog=threading.Timer(wall_seconds,expire)
        watchdog.daemon=True;watchdog.start()
        deadline=started+min(120,wall_seconds)
        def inspect(body):
            if expired.is_set() or time.monotonic()>deadline: raise PreparationError('target_timeout')
            if process.poll() is not None: raise PreparationError('local_validator_stopped')
            if artifact is not None: artifact.write(body+'\n')
            process.stdin.write(body+'\n')
            process.stdin.flush()
        result=_prepare_snapshot(path,timeout_seconds=max(0,deadline-time.monotonic()),inspect_part=inspect,inventory=True,target_day=target_day)
        process.stdin.close();process.stdin=None
        out,_=process.communicate(timeout=10)
        verified=json.loads(out)
        if process.returncode or verified.get('validator')!='inventory_complete':
            raise PreparationError('local_shared_validator_failed')
        if {k:v for k,v in result['rowCounts'].items() if v} != verified['rowCounts'] and not result['sourceIssues']:
            raise PreparationError('local_inventory_count_mismatch')
        verified['encodedRowCounts']=verified.pop('rowCounts')
        result.update(verified)
        result['sourceCompleteness']=not result['sourceIssues'] and verified['sharedValidationSafe']
        result['localSourceScanComplete']=result['sourceCompleteness']
        result['status']='complete_local_source_inventory' if result['sourceCompleteness'] else 'incomplete_source_inventory'
        if not result['sourceCompleteness']:
            result.pop('canonicalSourceDigest',None)
        for table, count in result['rowCounts'].items():
            stats=result['wireCompatibility']['tables'].setdefault(table,{'encoded':0,'fit':0,'blocked':0,'reasons':{},'examples':[]})
            stats['source']=count
            stats['unencoded']=count-stats['encoded']
            if stats['unencoded']<0:
                raise PreparationError('local_inventory_count_mismatch')
            stats['blocked']+=stats['unencoded']
            if stats['unencoded']:
                stats['reasons']['source_rejected']=stats['unencoded']
            if stats['fit']+stats['blocked']!=count:
                raise PreparationError('local_inventory_count_mismatch')
        result['wireCompatibility']['allRowsFit']=result['sourceCompleteness'] and result['wireCompatibility']['allRowsFit']
        result['uploadReady']=False
        result['elapsedSeconds']=round(time.monotonic()-started,3)
        result['cloudUpload']=False
        if artifact is not None:
            if not result['sourceCompleteness']: raise PreparationError('target_capture_not_validated')
            artifact.write(json.dumps({'captureManifest':result},separators=(',',':'))+'\n')
            artifact.flush();os.fsync(artifact.fileno());artifact.close();artifact=None
            # Hard link is atomic and refuses an existing destination.
            os.link(temp_path,capture_path);os.unlink(temp_path);temp_path=None
            result['status']='complete_targeted_local_capture'
            result['captureCreatedLocally']=True
        return result
    except PreparationError as error:
        return {'status':'blocked_incomplete_measurement','code':str(error),
            'diagnostics':error.diagnostics,'elapsedSeconds':round(time.monotonic()-started,3),'cloudUpload':False}
    except Exception:
        return {'status':'blocked_incomplete_measurement','code':'local_measurement_wall_timeout' if expired.is_set() else 'local_measurement_failed','cloudUpload':False}
    finally:
        if artifact is not None: artifact.close()
        if temp_path is not None: os.unlink(temp_path)
        if watchdog is not None: watchdog.cancel()
        if process is not None:
            if process.poll() is None: process.kill()
            if process.stdin is not None:
                try: process.stdin.close()
                except (BrokenPipeError, OSError): pass
                process.stdin=None
            try: process.communicate(timeout=3)
            except subprocess.TimeoutExpired:
                process.kill();process.wait(timeout=3)

if __name__=='__main__':
    if len(sys.argv)!=2 or sys.version_info<(3,13):
        raise SystemExit('Use existing project Python3.13+ and the exact verified backup path.')
    result=measure(Path(sys.argv[1]))
    print(json.dumps(result,separators=(',',':')))
    raise SystemExit(0 if result.get('sourceCompleteness') else 2)
